(function(){
'use strict';
function init(){
 const P=window.PlatformUI,original=document.getElementById('ovp'),old=document.getElementById('acctb-fopen');if(!original||!old)return;
 const E=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
 const types=[['model','Model'],['provider','Provider'],['agent','Source'],['person','User'],['team','Group'],['key','Agent key']].map(([key,label])=>({key,label}));
 const empty=()=>Object.fromEntries(types.map(t=>[t.key,[]])),copy=x=>Object.fromEntries(types.map(t=>[t.key,x[t.key].slice()]));let committed=empty(),draft=empty(),current=types[0];
 const trigger=document.getElementById('ovf-open').cloneNode(true);trigger.id='model-access-filter-trigger';trigger.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));trigger.removeAttribute('aria-controls');trigger.setAttribute('aria-expanded','false');trigger.querySelector('.hfb-text').replaceChildren(E('span','Filters'));old.replaceWith(trigger);document.getElementById('acctb-freset')?.remove();
 const clear=E('button','Clear','ovreset');clear.type='button';clear.hidden=true;trigger.after(clear);
 const panel=original.cloneNode(true);panel.classList.add('platform-access-filter-popup');panel.id='model-access-filter-panel';panel.removeAttribute('data-open');panel.inert=true;panel.setAttribute('aria-label','Filter model access');
 panel.querySelectorAll('[id]').forEach(n=>n.id=n.id.replace(/^ovp/,'maf'));panel.querySelectorAll('[for]').forEach(n=>n.htmlFor=n.htmlFor.replace(/^ovp/,'maf'));panel.querySelectorAll('[aria-describedby]').forEach(n=>n.setAttribute('aria-describedby',n.getAttribute('aria-describedby').replace(/^ovp/,'maf')));panel.querySelector('.ovscope-header strong').textContent='Filter models';panel.querySelector('.platform-copy-help').setAttribute('aria-label','How model filters work');document.body.append(panel);trigger.setAttribute('aria-controls',panel.id);
 const q=id=>panel.querySelector('#maf-'+id),list=q('list'),typeList=q('typelist'),search=q('search'),all=q('all'),allText=q('alltext'),apply=q('apply');
 const scope=E('section',undefined,'ovscope platform-access-filter-scope');scope.id='model-access-filter-scope';scope.hidden=true;document.getElementById('platform-access-controls').after(scope);
 function values(t){if(t.key==='model'||t.key==='provider')return [...new Set([...document.querySelectorAll('.accrow')].map(row=>t.key==='model'?row.dataset.model:row.dataset.prov))].sort();return P.accessScopes.find(s=>s.k===t.key)?.n||[]}
 function visible(){return values(current).filter(value=>value.toLowerCase().includes(search.value.toLowerCase()))}
 function mark(){return original.querySelector('#ovp-all').nextElementSibling.cloneNode(true)}
 function render(){
  typeList.replaceChildren();types.forEach(t=>{const b=E('button',undefined,'accp-type');b.type='button';b.dataset.type=t.key;b.setAttribute('aria-pressed',String(current===t));b.append(E('span',t.label),E('span',draft[t.key].length||'','accp-type-n'));b.onclick=()=>{current=t;search.value='';render()};typeList.append(b)});
  panel.querySelector('.ovscope-itemtitle').textContent=current.label+' · include any';search.placeholder='Search '+current.label.toLowerCase();search.setAttribute('aria-label','Search '+current.label.toLowerCase());q('ctrl').hidden=false;
  list.replaceChildren();const items=visible(),selection=draft[current.key];items.forEach(value=>{const label=E('label',undefined,'accp-item'),box=E('input');box.type='checkbox';box.checked=selection.includes(value);box.onchange=()=>{draft[current.key]=box.checked?[...selection,value]:selection.filter(v=>v!==value);render()};label.append(box,mark(),E('span',value));list.append(label)});if(!items.length)list.append(E('p','No matching '+current.label.toLowerCase()+'.','accp-empty'));
  const n=items.filter(value=>selection.includes(value)).length;all.checked=items.length>0&&n===items.length;all.indeterminate=n>0&&n<items.length;all.disabled=!items.length;allText.textContent='Select all ('+items.length+')';apply.disabled=types.every(t=>draft[t.key].length===committed[t.key].length&&draft[t.key].every(value=>committed[t.key].includes(value)));panel.querySelector('.accm-f button:first-child').disabled=types.every(t=>!draft[t.key].length);
 }
 function trash(){const n=E('span');n.innerHTML='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 6h18M9 6V4h6v2M5 6l1 14h12l1-14M10 10v6M14 10v6"/></svg>';return n.firstChild}
 function publish(){
  const active=types.filter(t=>committed[t.key].length);P.setAccessFilters(active.map(t=>({key:t.key,values:committed[t.key].slice()})));scope.replaceChildren();scope.hidden=!active.length;scope.toggleAttribute('data-filtered',!!active.length);clear.hidden=!active.length;trigger.toggleAttribute('data-on',!!active.length);trigger.querySelector('.hfb-text').textContent=active.length?'Filters · '+active.length:'Filters';
  const groups=E('div',undefined,'ovscope-groups');active.forEach((t,i)=>{const row=E('div',undefined,'ovscope-rule');row.append(E('span',i?'And':'Where','ovscope-connector'),E('span',t.label,'ovscope-category'),E('span','is any of','ovscope-operator'));const chips=E('div',undefined,'ovscope-values');committed[t.key].forEach(value=>{const chip=E('span',undefined,'ovscope-chip'),remove=E('button');remove.type='button';remove.setAttribute('aria-label','Remove '+value+' from '+t.label.toLowerCase()+' filter');remove.append(trash());remove.onclick=()=>{committed[t.key]=committed[t.key].filter(v=>v!==value);publish()};chip.append(E('span',value),remove);chips.append(chip)});const remove=E('button',undefined,'ovscope-remove-rule');remove.type='button';remove.setAttribute('aria-label','Remove '+t.label.toLowerCase()+' filter');remove.append(trash());remove.onclick=()=>{committed[t.key]=[];publish()};row.append(chips,remove);groups.append(row)});scope.append(groups);
 }
 P.clearModelAccessFilters=()=>{committed=empty();close();publish()};
 function close(){panel.removeAttribute('data-open');panel.inert=true;trigger.setAttribute('aria-expanded','false');if(panel.contains(document.activeElement))trigger.focus()}
 function position(){if(!panel.hasAttribute('data-open'))return;const r=trigger.getBoundingClientRect();panel.style.left=Math.max(8,Math.min(r.left,innerWidth-panel.offsetWidth-8))+'px';panel.style.top=Math.max(8,Math.min(r.bottom+8,innerHeight-panel.offsetHeight-8))+'px'}
 trigger.onclick=e=>{e.stopPropagation();if(panel.hasAttribute('data-open'))return close();draft=copy(committed);current=types.find(t=>committed[t.key].length)||types[0];search.value='';render();panel.inert=false;panel.setAttribute('data-open','');trigger.setAttribute('aria-expanded','true');position();search.focus()};
 search.oninput=render;all.onchange=()=>{const items=visible();draft[current.key]=all.checked?[...new Set([...draft[current.key],...items])]:draft[current.key].filter(v=>!items.includes(v));render()};apply.onclick=()=>{committed=copy(draft);close();publish()};q('cancel').onclick=close;panel.querySelector('.accm-f button:first-child').onclick=()=>{draft=empty();render()};clear.onclick=()=>{committed=empty();close();publish()};
 document.addEventListener('click',e=>{if(!e.composedPath().includes(panel)&&!trigger.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});window.addEventListener('resize',position);publish();
}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',()=>setTimeout(init,60)):setTimeout(init,60);
})();
